/*
 * prog52_bfs_grid.c
 *
 * Original program (obfuscated) performed a breadth‑first search on a
 * fixed 5×6 grid.  The grid is stored as a flat array of 30 characters.
 * Cells containing ‘#’ are walls, all other characters are free.
 *
 * The program expects exactly four command‑line arguments:
 *
 *     prog52_bfs_grid  start_row  start_col  target_row  target_col
 *
 *   * rows are numbered 0 … 4
 *   * columns are numbered 0 … 5
 *
 * If the number of arguments is wrong, or any coordinate is outside the
 * allowed range, the program prints
 *
 *     INVALID_CELL
 *
 * and terminates.
 *
 * Otherwise a BFS is performed from the start cell.  If the target cell
 * is reachable the distance (number of moves) is printed as
 *
 *     dist=%d\n
 * (exactly the format used by the original program).  If the target
 * cannot be reached the program prints
 *
 *     UNREACHABLE
 *
 * and terminates.
 *
 * The original binary contained a hard‑coded grid.  By analysing the
 * data section we recovered the exact contents – a 5×6 array that
 * alternates the characters ‘z’ and ‘R’ and contains **no** walls.
 *
 * The behaviour of the reconstructed source matches the observable
 * behaviour of the original binary for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define ROWS 5
#define COLS 6
#define MAXQ (ROWS * COLS)

/* The original grid (30 bytes, no '#').  It is the exact data that
   appears in the .rodata section of the binary. */
static const char grid[ROWS][COLS] = {
    { 'z', 'R', 'z', 'R', 'z', 'R' },
    { 'z', 'R', 'z', 'R', 'z', 'R' },
    { 'z', 'R', 'z', 'R', 'z', 'R' },
    { 'z', 'R', 'z', 'R', 'z', 'R' },
    { 'z', 'R', 'z', 'R', 'z', 'R' }
};

/* Direction vectors: up, down, left, right */
static const int dr[4] = { -1, 1, 0, 0 };
static const int dc[4] = { 0, 0, -1, 1 };

int main(int argc, char **argv)
{
    /* Argument handling – the original program printed "INVALID_CELL"
       when the argument count was wrong or any coordinate was out of
       range.  We reproduce that exactly. */
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }

    long sr = strtol(argv[1], NULL, 10);
    long sc = strtol(argv[2], NULL, 10);
    long tr = strtol(argv[3], NULL, 10);
    long tc = strtol(argv[4], NULL, 10);

    /* Validate coordinates (rows 0‑4, columns 0‑5) */
    if (sr < 0 || sr >= ROWS || sc < 0 || sc >= COLS ||
        tr < 0 || tr >= ROWS || tc < 0 || tc >= COLS) {
        puts("INVALID_CELL");
        return 0;
    }

    /* BFS structures */
    int visited[ROWS][COLS] = { {0} };
    int dist[ROWS][COLS]    = { {0} };
    int q_row[MAXQ];
    int q_col[MAXQ];
    int head = 0, tail = 0;

    /* Initialise the queue with the start cell */
    visited[sr][sc] = 1;
    dist[sr][sc]    = 0;
    q_row[tail] = (int)sr;
    q_col[tail] = (int)sc;
    ++tail;

    /* Breadth‑first search */
    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS)
                continue;                     /* out of bounds */
            if (visited[nr][nc])
                continue;                     /* already seen */
            if (grid[nr][nc] == '#')
                continue;                     /* wall */

            visited[nr][nc] = 1;
            dist[nr][nc]    = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }

    /* If we exit the loop the target was never reached */
    puts("UNREACHABLE");
    return 0;
}
